const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','censor.js','censor-backing.js','reverse-censor-plan.js','beatgrid.js','warp-loop.js','warp-loop-kernel.js','warp-loop-worklet.js','keylock.js','keylock-dsp.js','keylock-worker.js','warped-loop-censor-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`,value=(s,v)=>{$(s).value=String(v);};
const key=up=>document.body.dispatchEvent(new KeyboardEvent(up?'keyup':'keydown',{key:up?'u':'U',code:'KeyU',shiftKey:!up,bubbles:true,cancelable:true}));
const base64=b=>{let s='';for(let n=0;n<b.length;n+=16384)s+=String.fromCharCode(...b.subarray(n,n+16384));return btoa(s);};
function measure(data,sr,from,to){let sum=0;const a=Math.ceil(from*sr),b=Math.floor(to*sr),cross=[];assert(a>=0&&b<=data.length&&b>a,'Invalid declared window');for(let n=a;n<b;n++){sum+=data[n]**2;if(n>a&&data[n-1]<0&&data[n]>=0)cross.push((n-1-data[n-1]/(data[n]-data[n-1]))/sr);}return{rms:Math.sqrt(sum/(b-a)),hz:cross.length>3?(cross.length-1)/(cross.at(-1)-cross[0]):null};}
// Fixture arithmetic is independent of the reverse planner/engine timeline.
const beat=p=>p<1?2*p:p<1.8?2+(p-1)*2.5:4+(p-1.8)*1.5;
let app;
async function run(){
 const {engine,state}=app;$('#loop-censor-run').disabled=true;
 const report={startedAt:new Date().toISOString(),completed:false,criteria:{frequencyErrorHz:1,minimumRMS:.005,forwardClockStateSeconds:.01,muteAmplitudeRatio:[.60,.73]},scope:'Actual app grid/Smart Sync/U and Stem pad workflows for a known eight-beat warped loop; raw, keylocked+2, unlocked+2; prepared synthetic five-source PCM. Reverse repeats and exact forward owner return. Not native, physical, model inference, music-quality or full reference acceptance.',modes:[],checks:[],errors:[]};
 const reach=at=>until(()=>engine.ctx.currentTime>=at,'Declared audio time');
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical graph mute');await until(()=>!state.analysis,'Initial analysis');
  for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const sr=48000,duration=8,loopEnd=1.8+8/3;
  function tone(index,amplitude){const b=engine.ctx.createBuffer(2,sr*duration,sr),a=b.getChannelData(index);let phase=0;for(let n=0;n<a.length;n++){const t=n/sr,hz=index?550:t<1?220:t<1.8?330:440;phase+=2*Math.PI*hz/sr;a[n]=amplitude*Math.sin(phase);}return b;}
  for(let i=0;i<2;i++){const d=state.decks[i];Object.assign(d.track,{bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:true,loopIn:0,loopOut:i?4:loopEnd,slip:false,stemSlip:'off',sync:false,mode:'INT',level:.8,stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,tone(i,.12));engine.mix(i,'level',.8);}
  engine.stemBuffers.set(state.decks[0].track.id,[tone(0,.04),tone(0,.04),tone(0,.04),tone(0,0)]);
  click(button(0,'grid'));for(const marker of [{time:1,bpm:150},{time:1.8,bpm:90}]){value('#grid-warp-time',marker.time);value('#grid-warp-bpm',marker.bpm);click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Grid saved');
  click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');
  await engine.recordStart();report.recordStart=engine.recordStarted;
  for(const cfg of [{keylock:false,semitones:0},{keylock:true,semitones:2},{keylock:false,semitones:2}]){
   const d=state.decks[0],mode={...cfg,sections:[]};report.modes.push(mode);$('#loop-censor-status').textContent='Running '+JSON.stringify(cfg);
   if(d.keylock!==cfg.keylock){click(button(0,'keylock'));await until(()=>d.keylock===cfg.keylock,'Requested keylock');}
   while(d.keyShift<cfg.semitones){click(button(0,'keyUp'));await until(()=>!d.processing,'Key edit');}
   for(const deck of state.decks.slice(0,2))await engine.seek(deck,0);
   click(button(1,'sync'));click(button(1,'play'));await until(()=>state.decks[1].playing&&!state.decks[1].processing,'Primary');click(button(0,'sync'));click(button(0,'play'));await until(()=>d.playing&&!d.processing&&engine.voices.get(0)?.warpLoopTransport,'Warped loop');await reach(d.anchorTime+.25);
   const forward=engine.voices.get(0),clock=engine.voiceClock(d,forward);assert(d.syncState==='beat','Expected whole-bar Beat Sync');key(false);await until(()=>engine.deckScratchRequests.get(0)?.ready,'Loop Censor ready');const reverse=engine.voices.get(0),lease=reverse.censorBacking;assert(reverse.censorReverse?.outputs.length===5,'Expected five reverse sources');assert(reverse.censorBacking?.liveVoice===forward,'Lost forward owner');
   mode.start={when:d.anchorTime,position:d.anchorPosition,reverseLoop:reverse.censorReverse.snapshot().loop,rendered:reverse.censorReverse.snapshot().renderedLoop};
   const q=(8-beat(d.anchorPosition)+8)%8,cycle=d.anchorTime+(8-q)/2;
   // Fixed windows in the next COMPLETE reverse cycle and its following wrap.
   const windows=[{name:'reverse90',delta:.25,hz:440,rate:4/3},{name:'reverse150',delta:2.25,hz:330,rate:.8},{name:'reverse120',delta:3.25,hz:220,rate:1},{name:'wrapped90',delta:4.25,hz:440,rate:4/3}];
   for(const w of windows){const from=cycle+w.delta;mode.sections.push({name:w.name,from:from-engine.recordStarted,to:from-engine.recordStarted+.30,expectedLeft:w.hz*2**(cfg.semitones/12)*(cfg.keylock?1:w.rate),expectedRate:w.rate});await reach(from+.08);assert(engine.voices.get(0)===reverse,'Reverse owner changed');assert(Math.abs(engine.audibleRate(d)-w.rate)<1e-6,'Wrong reverse section rate');assert(d.syncState==='beat','Lost Beat Sync during Censor');await reach(from+.33);}
   // Same stable440Hz section after a wrap, mute one of three equal sources.
   click(button(0,'tab')+'[data-tab="Stems"]');click(button(0,'pad')+'[data-pad="0"]');assert(!d.stems[0],'Vocal mute');const muted=engine.ctx.currentTime;mode.sections.push({name:'wrapped90-vocal-muted',from:muted-engine.recordStarted+.07,to:muted-engine.recordStarted+.37,expectedLeft:440*2**(cfg.semitones/12)*(cfg.keylock?1:4/3)});await reach(muted+.40);
   await until(()=>{const p=clock(engine.ctx.currentTime);return p>=2.8&&p<=3.1;},'Declared forward return source section');key(true);await until(()=>!engine.deckScratchRequests.has(0)&&engine.voices.get(0)===forward,'Restore original loop');mode.return={actual:engine.position(d),expected:clock(engine.ctx.currentTime),originalOwner:engine.voices.get(0)===forward,loop:d.loop,bounds:[d.loopIn,d.loopOut],vocalMuted:!d.stems[0],syncState:d.syncState};assert(Math.abs(mode.return.actual-mode.return.expected)<.01&&d.loop&&d.loopIn===0&&d.loopOut===loopEnd&&d.syncState==='beat'&&!d.stems[0],'Return lost loop/clock/mute/Sync');assert(lease.pull.snapshot().retired,'Temporary silent pull was not released by production return');mode.pullAfterReturn=lease.pull.snapshot();mode.pullDisposal=await lease.pull.dispose();const returned=engine.ctx.currentTime;mode.sections.push({name:'forward90-vocal-muted',from:returned-engine.recordStarted+.15,to:returned-engine.recordStarted+.45,expectedLeft:440*2**(cfg.semitones/12)*(cfg.keylock?1:4/3)});await reach(returned+.50);click(button(0,'pad')+'[data-pad="0"]');
   for(let i=0;i<2;i++){click(button(i,'play'));await until(()=>!state.decks[i].playing,'Pause');click(button(i,'syncOff'));}report.checks.push(JSON.stringify(cfg)+' wraps in reverse and restores original forward loop owner');
  }
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  key(true);window.dispatchEvent(new Event('blur'));for(const d of state.decks)engine.pause(d);
  if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite recording');
   for(const mode of report.modes){mode.audio=mode.sections.map(w=>({...w,channels:[0,1].map(c=>measure(b.getChannelData(c),b.sampleRate,w.from,w.to))}));assert(mode.audio.length===6,'Missing declared windows');for(const w of mode.audio){assert(w.channels[0].rms>.005&&Math.abs(w.channels[0].hz-w.expectedLeft)<1,w.name+' left pitch/RMS');assert(w.channels[1].rms>.005&&Math.abs(w.channels[1].hz-550)<1,w.name+' opposite deck');}mode.muteRatios=[4,5].map(i=>mode.audio[i].channels[0].rms/mode.audio[3].channels[0].rms);assert(mode.muteRatios.every(r=>r>=.60&&r<=.73),'Reverse and returned five-source mute amplitude');}report.checks.push('Eighteen fixed master windows prove reversed section order, repeated wrap, key/pitch, audible forward return and opposite deck; retained source mute amplitude');
  }catch(error){report.errors.push({message:error.message,stack:error.stack});}}}
  report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#loop-censor-original').textContent=JSON.stringify(report,null,2);$('#loop-censor-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original'}:null},null,2);$('#loop-censor-status').textContent=report.completed?'Scoped warped-loop Censor passed; decks stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');const a=$('#loop-censor-download');a.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.download='warped-loop-censor-original.json';a.hidden=false;
 }
}
$('#loop-censor-run').onclick=run;async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#loop-censor-run').disabled=false;$('#loop-censor-run').textContent='Run one warped-loop Censor workflow';}boot().catch(e=>$('#loop-censor-status').textContent=e.message);
